# Generated by build.py from recipe.yml for recipe surl-hand-bound-ports-to-the-app. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site site2
printf '%s\n' 'Welcome aboard.' > site/greeting.txt
printf '%s\n' 'Welcome aboard.' > site2/greeting.txt
cat > run-tests.sh <<'EOF'
#!/bin/sh
# Starts surl on free ports, hands the bound URLs to the app, and checks what surl recorded.
# SITE names the directory to serve; it defaults to site.
out=$(mktemp)
log=$(mktemp)
surl -v --directory "${SITE:-site}" --mail-domain example.com --mailbox app@example.com:secret \
  http://127.0.0.1:0/ smtp://127.0.0.1:0/ > "$out" 2> "$log" &
surl_pid=$!
trap 'kill $surl_pid 2>/dev/null; rm -f "$out" "$log"' EXIT

# surl writes one Listening on line per listen URL once every listener has bound.
# If surl exits first, it refused to start: show why and stop with its exit code.
until [ "$(grep -c '^Listening on ' "$out")" -eq 2 ]; do
  kill -0 $surl_pid 2>/dev/null || { wait $surl_pid; code=$?; cat "$log" >&2; exit $code; }
  sleep 0.1
done

APP_HTTP_URL=$(sed -n 's|^Listening on \(http://.*\)$|\1|p' "$out")
APP_SMTP_URL=$(sed -n 's|^Listening on \(smtp://.*\)$|\1|p' "$out")
export APP_HTTP_URL APP_SMTP_URL
echo "the app gets $APP_HTTP_URL and $APP_SMTP_URL"
sh app.sh || exit

# What surl recorded: its log notes each message it stored, on its own time, so wait for the
# line for at most 10 s first.
i=0; until grep -q 'Message stored: ' "$log"; do i=$((i+1)); [ $i -ge 100 ] && break; sleep 0.1; done
grep -o 'Message stored: .*' "$log"
EOF
cat > app.sh <<'EOF'
#!/bin/sh
# Stands in for the app under test: it finds both servers through the environment alone.
greeting=$(curl -fsS "${APP_HTTP_URL}greeting.txt") || exit
printf 'Subject: Welcome\r\n\r\n%s\r\n' "$greeting" |
  curl -sS -u app@example.com:secret --mail-from app@example.com --mail-rcpt app@example.com \
    -T - "${APP_SMTP_URL}example.com" || exit
echo "the app mailed: $greeting"
EOF
cat > run-twice.sh <<'EOF'
#!/bin/sh
# Runs the tests twice at once, the first serving directory $1 and the second $2.
SITE=$1 sh run-tests.sh > run1.txt 2>&1 &
first=$!
SITE=$2 sh run-tests.sh > run2.txt 2>&1 &
second=$!
wait $first; a=$?
wait $second; b=$?
if [ $a -le $b ]; then echo "exit codes: $a $b"; else echo "exit codes: $b $a"; fi
if [ $a -eq 0 ] && [ $b -eq 0 ] && [ "$(head -n 1 run1.txt)" != "$(head -n 1 run2.txt)" ]; then
  echo "each run got its own ports"
fi
grep -h -o 'is in use by another surl process' run1.txt run2.txt || true
EOF
sh run-tests.sh
